add_action( 'woocommerce_thankyou', 'privytics_track_order' );

function privytics_track_order( $order_id ) {
	$order = wc_get_order( $order_id );

	// Send each order only once, even if the thank-you page is refreshed.
	if ( ! $order || $order->get_meta( '_privytics_tracked' ) ) {
		return;
	}
	$order->update_meta_data( '_privytics_tracked', 'yes' );
	$order->save();

	$data = array(
		'revenue'  => (float) $order->get_total(),
		'currency' => $order->get_currency(),
		'order_id' => (string) $order->get_order_number(),
	);

	echo '<script>window.op("track","purchase_completed",'
		. wp_json_encode( $data, JSON_HEX_TAG | JSON_HEX_AMP ) . ');</script>';
}
